using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using UnityEngine;

namespace AshinaStudio {
 public sealed class MatchChecks : MonoBehaviour {
  public StudioApp App;public string Output;public bool Client;readonly List<string> passed=new List<string>();readonly List<Bot> bots=new List<Bot>();double sent;
  sealed class Bot:IDisposable {public MatchLink Link;public RobotProject Project;public string Id;public MatchSnapshot State;public Vector3 Drive;public bool Fire,Intake,Live=true;public long Sequence;public void Dispose(){Live=false;Link.Dispose();}}
  void Check(bool ok,string name){if(!ok)throw new Exception(name);passed.Add(name);Debug.Log("PASS ONLINE: "+name);}
  async Task Until(Func<bool> condition,string name,double timeout=15){double start=MatchLink.Clock;while(!condition()){if(MatchLink.Clock-start>timeout)throw new Exception("Timeout: "+name);await Task.Delay(20);}Check(true,name);}
  static RobotProject TestProject(){var p=RobotProject.Empty();p.training.fuelCount=456;p.training.spawnFuel=true;p.training.recycleFuel=false;p.training.capacity=3;p.training.capacitySeason="2026";p.inventory["fuel"]=2;p.network.driveFromNt=false;p.parts.Add(new RobotPart{id="axis",name="Generic moving part",position=new[]{0.0,0,.5}});p.actions.Add(new RobotAction{id="intake",type="capture",partId="chassis",piece="fuel",key="",button="",spawn=new[]{.6,0,.0},captureSize=new[]{.5,1.0,.5},captureEfficiency=1});p.actions.Add(new RobotAction{id="fire",type="emit",partId="chassis",piece="fuel",key="",button="",spawn=new[]{.65,0,.4},pitch=40,speed=5,interval=.1});return p;}
  async void Start(){Directory.CreateDirectory(Output);try{if(Client)await ClientRun();else await HostRun();File.WriteAllText(Path.Combine(Output,"result.json"),JsonConvert.SerializeObject(new{success=true,count=passed.Count,passed},Formatting.Indented));Application.Quit(0);}catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(Output,"result.json"),JsonConvert.SerializeObject(new{success=false,count=passed.Count,passed,error=e.ToString()},Formatting.Indented));Application.Quit(1);}finally{foreach(var bot in bots)bot.Dispose();}}
  void Update(){
   foreach(var bot in bots.Where(b=>b.Live))while(bot.Link.Take(out var packet)){if((string)packet["type"]=="welcome"){bot.Id=(string)packet["id"];bot.Link.Send(new{type="ready",value=true});}if((string)packet["type"]=="state")bot.State=packet.ToObject<MatchSnapshot>();}
   if(MatchLink.Clock-sent<.02)return;sent=MatchLink.Clock;foreach(var bot in bots.Where(b=>b.Live&&b.Id!=null))bot.Link.Send(new MatchInput{sequence=++bot.Sequence,echo=MatchLink.Clock,drive=new[]{bot.Drive.z,-bot.Drive.x,0},parts=bot.Project.parts.Select(p=>new MatchPartState{id=p.id,p=MatchProtocol.V(Frc.Position(p.position)),q=MatchProtocol.Q(Frc.Rotation(p.rotation))}).ToArray(),actions=bot.Project.actions.Select(a=>new MatchActionInput{id=a.id,down=a.type=="emit"?bot.Fire:bot.Intake,pitch=(float)a.pitch,yaw=(float)a.yaw,speed=(float)a.speed}).ToArray()},true);
  }
  async Task TransferProgress(){
   using(var listener=new MatchListener(0,true))using(var raw=new System.Net.Sockets.TcpClient()){
    await raw.ConnectAsync("127.0.0.1",listener.Port);MatchLink peer=null;await Until(()=>listener.Take(out peer),"TCP listener accepts a split-frame transfer");using(peer){var stream=raw.GetStream();await stream.WriteAsync(new byte[]{0,0,16,0},0,4);await Task.Delay(60);double before=peer.LastReceived;await stream.WriteAsync(new byte[128],0,128);await Task.Delay(60);Check(peer.LastReceived>before&&peer.Connected&&!peer.Take(out _),"Partial model traffic updates liveness before a large frame completes");}
   }
  }
  async Task HostRun(){
   await TransferProgress();var p=TestProject();p.network.robotProject="PRIVATE_LOCAL_PROJECT";p.blocklyProject=JObject.FromObject(new{privateToken="PRIVATE_BLOCK_TOKEN"});await App.LoadProject(p);App.EnterWorkspace();App.CheckInput=false;App.CheckVelocity=Vector3.zero;
   string shared=MatchProtocol.Encode(MatchProtocol.Share(p));Check(!shared.Contains("PRIVATE_LOCAL_PROJECT")&&!shared.Contains("PRIVATE_BLOCK_TOKEN"),"Room sharing excludes local code path and Blockly state");
   Check(await App.HostRoom(0,"Native host","blue",true),"Native application hosts a real TCP room");var room=App.Room;Check(App.RoomInvitation.StartsWith("127.0.0.1:"),"Loopback-only room advertises a reachable loopback invitation");Check(room.Robots.Count==1&&!App.NetworkPoseOwned,"Room owns chassis physics instead of observed NT poses");
   using(var wrong=await MatchLink.Connect("127.0.0.1",room.Port)){wrong.Send(new{type="join",protocol=1,key=new string('0',32),name="Bad key",alliance="red",project=MatchProtocol.Share(p)});string error=null;await Until(()=>{while(wrong.Take(out var packet))if((string)packet["type"]=="error")error=(string)packet["message"];return error!=null;},"Wrong room key is rejected");}
   for(int i=0;i<4;i++){var bot=new Bot{Project=MatchProtocol.Share(p),Link=await MatchLink.Connect("127.0.0.1",room.Port)};bots.Add(bot);bot.Link.Send(new{type="join",protocol=1,key=room.Token,name="Manual robot "+(i+1),alliance=i<2?"blue":"red",project=bot.Project});await Until(()=>bot.Id!=null,"Remote manual robot "+(i+1)+" joins");}
   bool cloud=Environment.GetCommandLineArgs().Contains("--room-cloud-check");
   if(cloud){await room.EnableInternet(App.CloudRoomExecutable);Check(room.InternetInvitation.StartsWith("https://"),"Internet invitation reaches the local host through Cloudflare");}
   File.WriteAllText(Path.Combine(Output,"room.json"),JsonConvert.SerializeObject(new{invitation=cloud?room.InternetInvitation:"127.0.0.1:"+room.Port+"/"+room.Token,port=room.Port,key=room.Token}));
   await Until(()=>room.Robots.Count==6,"Six players join the same authoritative field",40);await Until(()=>room.Robots.Values.Count(r=>r.Ready)==5,"Remote players become ready",30);
   using(var seventh=await MatchLink.Connect("127.0.0.1",room.Port)){seventh.Send(new{type="join",protocol=1,key=room.Token,name="Seventh",alliance="red",project=MatchProtocol.Share(p)});bool rejected=false;await Until(()=>{while(seventh.Take(out var packet))if((string)packet["type"]=="error")rejected=true;return rejected;},"Seventh player is rejected");}
   Check(!room.StartMatch(),"Host cannot start before every player is ready");room.SetReady(true);room.AutoSeconds=2;room.TeleopSeconds=12;room.CountdownSeconds=.4;room.GapSeconds=.3;Check(room.StartMatch(),"Host starts all ready robots with a shared countdown");
   await Until(()=>room.Phase=="autonomous"&&App.Running,"Autonomous enables the shared room");await Until(()=>room.Robots.Values.Any(r=>r.Name=="Native WPILib client"&&r.Shots==2),"Remote code fires only its two stored pieces",5);
   var native=room.Robots.Values.First(r=>r.Name=="Native WPILib client");Check(native.Project.inventory["fuel"]==0,"Code-triggered emission consumes server-owned stock");
   await Until(()=>room.Phase=="transition"&&!App.Running,"Auto-to-teleop gap disables robots");await Until(()=>room.Phase=="teleop"&&App.Running,"Teleop follows the same server clock");
   App.Pieces.Clear();var a=room.Robots[bots[0].Id];var b=room.Robots[bots[2].Id];
   a.Project.inventory["fuel"]=0;b.Project.inventory["fuel"]=0;a.Chassis.Teleport(Frc.Position(new[]{8.0,4,0.0}),Quaternion.identity);b.Chassis.Teleport(Frc.Position(new[]{8.0,4,0.0}),Quaternion.identity);
   var pickup=App.Pieces.Spawn("fuel",a.Nodes["chassis"].content.TransformPoint(Frc.Position(p.actions[0].spawn)),Vector3.zero,Quaternion.identity);bots[0].Intake=bots[2].Intake=true;await Task.Delay(140);bots[0].Intake=bots[2].Intake=false;
   Check(a.Pickups+b.Pickups==1&&!App.Pieces.Active.Contains(pickup),"Two intakes cannot claim the same shared piece");
   a.Project.inventory["fuel"]=3;App.Pieces.Spawn("fuel",a.Nodes["chassis"].content.TransformPoint(Frc.Position(p.actions[0].spawn)),Vector3.zero,Quaternion.identity);bots[0].Intake=true;await Task.Delay(100);bots[0].Intake=false;Check(a.Project.inventory["fuel"]==3,"Server enforces individual inventory capacity");
   a.Project.inventory["fuel"]=1;int before=a.Shots;bots[0].Fire=true;await Task.Delay(450);bots[0].Fire=false;Check(a.Shots==before+1&&a.Project.inventory["fuel"]==0,"Held firing cannot exceed collected inventory");
   await OnlineAimChecks(a);
   App.Pieces.Clear();var goal=App.Hubs.First(h=>h.Alliance=="blue");App.Pieces.Spawn("fuel",goal.Center+Vector3.up*(goal.Height+.1f),Vector3.down*2,Quaternion.identity);await Until(()=>App.BlueFuel==1,"Host scores a real descending HUB crossing");await Until(()=>bots.All(x=>x.State!=null&&x.State.blue==1),"Shared score reaches every manual client");
   // Put the real WPILib participant in a collision. Its speed request stays forward.
   a.Chassis.Teleport(Frc.Position(new[]{7.7,4,0.0}),Quaternion.identity);native.Chassis.Teleport(Frc.Position(new[]{9.7,4,0.0}),Frc.Rotation(new[]{0.0,0,180}));bots[0].Drive=Vector3.forward*1.2f;
   await Task.Delay(1800);float separation=Vector3.Distance(a.Root.position,native.Root.position);Check(separation>.65f&&separation<1.4f,"Two independently controlled robot bodies collide without passing through");
   File.WriteAllText(Path.Combine(Output,"collision.json"),JsonConvert.SerializeObject(new{pose=Frc.Position(native.Root.position),velocity=Frc.Position(native.Chassis.Body.linearVelocity),separation}));
   bots[0].Drive=Vector3.zero;long seq=a.LastSequence;Check(!a.Submit(new MatchInput{sequence=seq}),"Old or malformed input sequences cannot overwrite current controls");
   var stale=room.Robots[bots[1].Id];bots[1].Drive=Vector3.forward;await Task.Delay(250);bots[1].Live=false;await Task.Delay(650);Check(MatchLink.Clock-stale.InputAt>.35&&stale.Chassis.Body.linearVelocity.magnitude<.35,"Stale input brakes a robot instead of continuing the last command");bots[1].Live=true;
   await Until(()=>File.Exists(Path.Combine(Path.GetDirectoryName(Output),"client/probe-ready.json")),"Native client confirms replication, WPILib odometry and vision",15);
   room.ReturnLobby();await Task.Delay(180);Check(room.Phase=="lobby"&&!App.Running&&App.BlueFuel==0&&room.Robots.Values.All(r=>r.Shots==0),"Returning to lobby resets phase, shared score and per-robot stock");
   bots[3].Dispose();await Until(()=>room.Robots.Count<=5,"Disconnected robot leaves the roster and physics world");
   room.Dispose();await Until(()=>File.Exists(Path.Combine(Path.GetDirectoryName(Output),"client/result.json")),"Native client handles host shutdown",15);var client=JObject.Parse(File.ReadAllText(Path.Combine(Path.GetDirectoryName(Output),"client/result.json")));Check((bool)client["success"],"Separate native application passes client checks");
   await App.LeaveRoom();Check(!App.RoomActive&&App.Project.network.robotProject=="PRIVATE_LOCAL_PROJECT"&&App.Project.inventory["fuel"]==2,"Leaving restores the saved offline robot configuration");await CageReplication();
  }
  async Task OnlineAimChecks(MatchRobot actor){
   var shot=actor.Project.actions.First(x=>x.type=="emit");var original=JsonConvert.DeserializeObject<RobotAction>(JsonConvert.SerializeObject(shot));int index=actor.Project.actions.IndexOf(shot);var position=Frc.Position(actor.Root.position);shot.aimMode="point";shot.target=new[]{position[0]+2,position[1],1.0};shot.maxShotSpeed=1;actor.Project.inventory["fuel"]=1;int before=actor.Shots;bots[0].Fire=true;await Task.Delay(200);bots[0].Fire=false;
   Check(actor.Shots==before&&actor.Project.inventory["fuel"]==1,"Online point aiming rejects insufficient power without consuming inventory");
   shot.maxShotSpeed=12;shot.inheritVelocity=false;shot.spreadDegrees=0;var sample=new MatchActionInput{pitch=40,yaw=0,speed=5};var mount=actor.Nodes[shot.partId].content;float normal=Mathf.Asin((mount.rotation*Frc.Direction(40,0)).y)*Mathf.Rad2Deg;var aimed=actor.Emit(App.Pieces,shot,sample);Check(aimed!=null&&Math.Abs(Mathf.Asin(aimed.Body.linearVelocity.normalized.y)*Mathf.Rad2Deg-normal)<.05&&aimed.Body.linearVelocity.magnitude<=12,"Online target solver preserves normal elevation and maximum launch speed");
   shot.aimMode="zones";shot.zones.Add(new AimZone{center=new[]{position[0],position[1]},size=new[]{4.0,4.0},target=new[]{position[0]-2,position[1],.1}});actor.Project.inventory["fuel"]=1;var feed=actor.Emit(App.Pieces,shot,sample);Check(feed!=null&&feed.Body.linearVelocity.z<0,"Online region target can feed backward toward the team's side");
   shot.aimMode="point";shot.target=new[]{1000.0,1000,10};actor.Project.inventory["fuel"]=1;sample.code=true;sample.pitch=25;sample.yaw=-30;sample.speed=3;var code=actor.Emit(App.Pieces,shot,sample);Check(code!=null&&Math.Abs(code.Body.linearVelocity.magnitude-3)<.01&&Vector3.Angle(code.Body.linearVelocity,mount.rotation*Frc.Direction(25,-30))<.05,"Code-owned shot parameters override offline target assistance on the host");actor.Project.actions[index]=original;
  }
  async Task CageReplication(){
   var original=ProjectIO.Parse(ProjectIO.Write(App.Project));await App.LoadField("2025");var replica=new FieldWorld();await replica.Load("2025",false);using(var host=new MatchFieldSync(App.Field,true))using(var client=new MatchFieldSync(replica,false)){Check(host.Count==6&&client.Count==6,"All six REEFSCAPE cages have stable shared identities");Check(replica.Root.GetComponentsInChildren<HangingCage>(true).All(c=>c.Body.isKinematic),"Client cages cannot run a competing suspension simulation");var cage=App.Field.Root.GetComponentsInChildren<HangingCage>().First();var before=cage.transform.position;cage.Body.AddForce(Vector3.right*35,ForceMode.Impulse);await Task.Delay(250);var packet=JsonConvert.DeserializeObject<MatchFieldState[]>(JsonConvert.SerializeObject(host.Snapshot()));client.Apply(packet);var mirrored=client.Snapshot();Check(Vector3.Distance(before,cage.transform.position)>.01f&&packet.All(s=>Vector3.Distance(MatchProtocol.Vector(s.p),MatchProtocol.Vector(mirrored[s.id].p))<.001f&&Quaternion.Angle(MatchProtocol.Rotation(s.q),MatchProtocol.Rotation(mirrored[s.id].q))<.05f),"A physically swinging cage replicates its position and rotation");}replica.Dispose();await App.LoadProject(original);
  }
  async Task ClientRun(){
   var args=Environment.GetCommandLineArgs();string invitation=args[Array.IndexOf(args,"--room-invite")+1];var p=TestProject();p.network.host="127.0.0.1";p.network.port=5813;p.network.driveFromNt=true;p.network.mode="physics";p.network.vision=true;p.parts[1].links.Add(new AxisLink{topic="/OnlineTest/axis",property="rotation.z"});p.actions[1].topic="/OnlineTest/fire";p.actions[1].ntSource=true;p.cameras.Add(new CameraData{position=new[]{.2,0,.5},range=50});await App.LoadProject(p);App.EnterWorkspace();App.ConnectNetwork();await Until(()=>App.Nt.Connected&&App.Nt.Get("/OnlineTest/fire")!=null,"Native client connects to its own real WPILib NT server");
   Check(await App.JoinRoom(invitation,"Native WPILib client","red"),"Separate native application joins using its invitation");await Until(()=>App.Room.CanReady&&App.Room.Robots.Count==6,"Native client builds all six shared robot models",35);await Until(()=>App.Pieces.Active.Count==456,"Full 456-piece field replicates before players enable");Check(App.Room.FieldHash==MatchProtocol.FieldSignature(Application.streamingAssetsPath,App.Project.season,App.Project.tagLayout),"Client and host agree on official field collision and AprilTag assets");App.Room.SetReady(true);
   Check(App.SelectRoomAuto("/SmartDashboard/Auto","Feed"),"Room UI selects the existing WPILib autonomous chooser");await Until(()=>App.Nt.Get("/OnlineTest/chooserSeen")?.Value is bool chosen&&chosen,"Robot code receives the chosen autonomous command");await Until(()=>App.Room.Phase=="autonomous"&&App.Running,"Client receives synchronized autonomous enable",30);Check(!App.NetworkPoseOwned,"Online client does not teleport from its local odometry");
   await Until(()=>App.ShotsFired==2&&App.Stored("fuel")==0,"Client receives server-owned shot count and empty inventory",5);
   await Until(()=>App.Nt.Get("/OnlineTest/autoSeen")?.Value is bool auto&&auto,"WPILib DriverStation sees autonomous mode");
   await Until(()=>App.Room.Phase=="teleop"&&App.Running,"Client receives synchronized teleop enable");await Until(()=>App.Nt.Get("/OnlineTest/teleopSeen")?.Value is bool tele&&tele,"WPILib DriverStation sees teleop mode");
   await Until(()=>App.BlueFuel==1,"Native client receives the shared HUB score");
   await Until(()=>App.Nt.Get("/OnlineTest/visionSeen")?.Value is bool vision&&vision,"Local robot code receives simulated AprilTag camera data");
   await Until(()=>App.Nt.Get("/OnlineTest/odoSamples")?.Value!=null&&Convert.ToInt64(App.Nt.Get("/OnlineTest/odoSamples").Value)>50,"Wheel and gyro adapter updates a real WPILib odometry estimator");
   await Task.Delay(2200);var own=App.Room.State.robots.First(r=>r.id==App.Room.LocalId);var truth=MatchProtocol.Vector(own.p);Check(Vector3.Distance(App.Robot.position,truth)<.35f,"Local robot pose follows the shared collision result");
   Check(App.Room.Robots.Values.Where(r=>r.Id!=App.Room.LocalId).All(r=>r.Chassis==null),"Client replicas cannot create competing robot physics");Check(App.Pieces.Active.All(piece=>piece.Body.isKinematic),"Client game pieces are replicas of the host world");
   Check(Math.Abs(Frc.Euler(App.Nodes["axis"].transform.localRotation)[2]-35)<.1,"Generic NT mechanism angles reach the online robot");
   var reflected=App.Room.State.robots.First(r=>r.id==App.Room.LocalId).parts.First(part=>part.id=="axis");Check(Math.Abs(Frc.Euler(MatchProtocol.Rotation(reflected.q))[2]-35)<.1,"Server replicates live mechanism motion to other players");
   Check(Convert.ToDouble(App.Nt.Get("/OnlineTest/odoError").Value)<.12,"WPILib wheel and gyro odometry agrees with shared field truth");
   Check(App.Nt.Get("/OnlineTest/allianceSeen")?.Value is bool alliance&&alliance,"WPILib receives its own alliance and driver station slot");
   File.WriteAllText(Path.Combine(Output,"probe-ready.json"),"{}");await Until(()=>!App.Room.Connected&&!App.Running,"Losing the host disables the native client");await Until(()=>App.Nt.Get("/OnlineTest/disabledSeen")?.Value is bool disabled&&disabled,"WPILib disables after shared match control is lost");await App.LeaveRoom();Check(!App.RoomActive&&!App.Running,"Disconnected client returns to its offline robot project");
  }
 }
}
